pub const Conf = struct { base_urlz_main: []const u8 = "https://www.facebook.com", path_home_main: []const u8 = "/", path_mark_crea: []const u8 = "/marketplace/create/item", path_mark_sell: []const u8 = "/marketplace/you/selling", path_noti_comm: []const u8 = "/notifications", path_dmsg_thre: []const u8 = "/messages/t/", data_loca_wind: []const u8 = "E:\\.zz-base-home-tena\\as-apps\\ch-chat\\fb-face-webs", data_loca_unix: []const u8 = "~/.zz-base-home-tena/as-apps/ch-chat/fb-face-webs", brow_exec_path: []const u8 = "", brow_head_mode: bool = false, brow_time_seco: u32 = 60, type_dely_msec: [2]u32 = .{ 90, 260 }, acti_dely_secs: [2]u32 = .{ 8, 40 }, mous_step_coun: u32 = 18, time_scal_perc: u32 = 100, rand_seed_numb: u64 = 0, capz_post_dayz: u32 = 3, capz_comm_dayz: u32 = 30, capz_mark_dayz: u32 = 2, capz_grou_dayz: u32 = 5, capz_frie_dayz: u32 = 5, capz_dmsg_dayz: u32 = 30, capz_reac_dayz: u32 = 60, quie_hour_rang: [2]u8 = .{ 23, 6 }, quie_zone_minu: i32 = 420, warm_dayz_coun: u32 = 14, retr_coun_maxz: u32 = 3, smar_mode_enab: bool = false, smar_chai_orde: []const []const u8 = &.{ "clau", "llam" }, smar_clau_exec: []const u8 = "claude", smar_llam_urlz: []const u8 = "http://127.0.0.1:8080", smar_time_seco: u32 = 90, repl_temp_list: []const []const u8 = &.{ "Thank you!", "Thanks for asking, I will message you." }, labl_post_open: []const []const u8 = &.{ "What's on your mind", "Create a post", "Bạn đang nghĩ gì" }, labl_post_boxz: []const []const u8 = &.{ "Post text", "What's on your mind", "Create a post" }, labl_post_subm: []const []const u8 = &.{ "Post", "Đăng" }, labl_comm_boxz: []const []const u8 = &.{ "Write a comment", "Write a reply", "Viết bình luận" }, labl_repl_btnz: []const []const u8 = &.{ "Reply", "Phản hồi", "Trả lời" }, labl_dmsg_boxz: []const []const u8 = &.{ "Message", "Nhắn tin" }, labl_mark_titl: []const []const u8 = &.{ "Title", "Tiêu đề" }, labl_mark_pric: []const []const u8 = &.{ "Price", "Giá" }, labl_mark_desc: []const []const u8 = &.{ "Description", "Mô tả" }, labl_mark_subm: []const []const u8 = &.{ "Publish", "Đăng" }, labl_mark_done: []const []const u8 = &.{ "published", "Your listing is live", "đã đăng" }, labl_mark_renw: []const []const u8 = &.{ "Renew", "Gia hạn" }, labl_mark_sold: []const []const u8 = &.{ "Mark as sold", "Đánh dấu là đã bán" }, labl_grou_join: []const []const u8 = &.{ "Join group", "Tham gia nhóm" }, labl_frie_addz: []const []const u8 = &.{ "Add friend", "Thêm bạn bè" } };
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err| { if (err == error.FileNotFound) return .{}; return err; }; return confParse(allo, byte); }
pub fn confParse(allo: std.mem.Allocator, byte: []const u8) !Conf { const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if (conf.type_dely_msec[0] > conf.type_dely_msec[1] or conf.type_dely_msec[0] == 0) return error.BadConfig; if (conf.acti_dely_secs[0] > conf.acti_dely_secs[1]) return error.BadConfig; if (conf.quie_hour_rang[0] > 23 or conf.quie_hour_rang[1] > 23) return error.BadConfig; if (conf.time_scal_perc > 1000 or conf.mous_step_coun == 0 or conf.mous_step_coun > 200) return error.BadConfig; if (conf.retr_coun_maxz == 0 or conf.retr_coun_maxz > 10 or conf.brow_time_seco == 0) return error.BadConfig; if (conf.quie_zone_minu < -840 or conf.quie_zone_minu > 840) return error.BadConfig; if (!std.mem.startsWith(u8, conf.base_urlz_main, "http")) return error.BadConfig; for (conf.smar_chai_orde) |ite| if (!std.mem.eql(u8, ite, "clau") and !std.mem.eql(u8, ite, "llam")) return error.BadConfig; }
pub fn dataDir(allo: std.mem.Allocator, home: []const u8, conf: Conf) ![]u8 { return pathExpa(allo, home, if (builtin.os.tag == .windows) conf.data_loca_wind else conf.data_loca_unix); }
pub fn subDir(allo: std.mem.Allocator, home: []const u8, conf: Conf, subz: []const u8) ![]u8 { const root = try dataDir(allo, home, conf); defer allo.free(root); return std.fs.path.join(allo, &.{ root, subz }); }
pub fn pathExpa(allo: std.mem.Allocator, home: []const u8, path: []const u8) ![]u8 { if (path.len > 0 and path[0] == CF.tilz) { if (home.len == 0) return error.BadConfig; return std.fmt.allocPrint(allo, "{s}{s}", .{ home, path[1..] }); } return allo.dupe(u8, path); }
